const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define reservoir location (Omkareshwar Dam on Narmada River)
  const reservoir = ee.Geometry.Point([76.15, 22.27]).buffer(2000);

  // Date ranges
  const date1Start = '2023-02-07';
  const date1End = '2023-02-13';
  const date2Start = '2025-01-27';
  const date2End = '2025-02-02';

  // Function to mask clouds
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Get Sentinel-2 collections
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(reservoir)
    .filterDate(date1Start, date1End)
    .map(maskClouds);

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(reservoir)
    .filterDate(date2Start, date2End)
    .map(maskClouds);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`2023 Images: ${size1}`);
  console.log(`2025 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Get median composites
  const img1 = col1.median();
  const img2 = col2.median();

  // Detect solar panels using brightness and low NDVI
  // Solar panels are bright but not vegetation
  function detectPanels(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']);
    const brightness = image.select(['B2', 'B3', 'B4']).reduce(ee.Reducer.mean());

    // Solar panels: high brightness, low-medium NDVI
    const panels = brightness.gt(1500)
                    .and(ndvi.lt(0.3))
                    .and(ndvi.gt(-0.2));
    return panels;
  }

  const panels1 = detectPanels(img1);
  const panels2 = detectPanels(img2);

  // Count valid pixels
  const count1 = await panels1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 10,
    maxPixels: 1e9
  }).get('B2').getInfo();

  const count2 = await panels2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 10,
    maxPixels: 1e9
  }).get('B2').getInfo();

  console.log(`Panel pixels 2023: ${count1}`);
  console.log(`Panel pixels 2025: ${count2}`);

  if (count1 === null || count2 === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (count1 === 0 && count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Compare panel coverage
  if (count1 > count2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
